"""
    Edit a string by replacing underscores with spaces and removing commas, single quotes and new line characters
    :param input_string: the string which needs to be altered
    :return: edited string
    """
def remove_invalid_characters(input_string: Any) -> object {
    return input_string.replace(" ", "_").replace(",", "").replace("'", "").replace(
        "\n", ""
    ).replace(
        "/", "_"
    ).replace(
        ":", ""
    );
}

"""
    Controls like throttle, steer, pitch, yaw, and roll need to be in the range of -1 to 1.
    This will ensure your number is in that range. Something like 0.45 will stay as it is,
    but a value of -5.6 would be changed to -1.
    """
def limit_to_safe_range(value: float) -> float {
    if (value < -1) {
        return -1;
    }
    if (value > 1) {
        return 1;
    }
    return value;
}

